targets.expr:
avg by(UUID, Hostname, gpu, modelName, device, pci_bus_id) (
  stddev_over_time(DCGM_FI_DEV_POWER_USAGE{Hostname=~"$hostname",UUID=~"$UUID"}[15m])
)

avg by(UUID, Hostname, gpu, modelName, device, pci_bus_id) (
  rate(DCGM_FI_DEV_PCIE_REPLAY_COUNTER{Hostname=~"$hostname",UUID=~"$UUID"}[5m])
)

avg by(UUID, Hostname, gpu, modelName, device, pci_bus_id) (
  rate(DCGM_FI_PROF_PCIE_TX_BYTES{Hostname=~"$hostname",UUID=~"$UUID"}[5m])
)

avg by(UUID, Hostname, gpu, modelName, device, pci_bus_id) (
  rate(DCGM_FI_PROF_PCIE_RX_BYTES{Hostname=~"$hostname",UUID=~"$UUID"}[5m])
)
